import { useState, useEffect } from 'react';
import axios from 'axios';
import { TextField, Button, Paper, Typography } from '@mui/material';
import InputLabel from '@mui/material/InputLabel';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';          // ← Change to Select
import MenuItem from '@mui/material/MenuItem';      // ← Add MenuItem

export default function AddProduct() {
  const [product, setProduct] = useState({
    name: "",
    description: "",
    price: "",
    quantity: "",
    categoryId: ""
  });

  const [categories, setCategories] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:7000/category/getCategory")
      .then((res) => {
        setCategories(res.data.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const handleChange = (e) => {
    setProduct({
      ...product,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async () => {
    try {
      const sendData = {
        name: product.name,
        description: product.description,
        price: Number(product.price),        // ← Convert to number
        quantity: Number(product.quantity),  // ← Convert to number
        categoryId: product.categoryId
      };

      console.log("Sending:", sendData);
      const res = await axios.post(
        "http://localhost:7000/product/addProduct",
        sendData  // ← Send sendData not product
      );

      console.log(res.data);
      alert("Product Added Successfully");

      setProduct({
        name: "",
        description: "",
        price: "",
        quantity: "",
        categoryId: ""
      });

    } catch (error) {
      console.log(error.response.data);  // ← This will show exact error
      alert("Error adding Product");
    }
  };

  return (
    <div>
      <Paper elevation={20} style={{ width: "400px", padding: "30px", margin: "auto" }}>
        
        <Typography variant='h5' style={{ textAlign: "center" }}>
          Add Product
        </Typography>

        <TextField
          label="Name"
          name="name"
          value={product.name}
          fullWidth
          onChange={handleChange}
          style={{ marginBottom: "20px", marginTop: "20px" }}
        />

        <TextField
          label="Description"
          name="description"
          value={product.description}
          fullWidth
          onChange={handleChange}
          style={{ marginBottom: "20px", marginTop: "20px" }}
        />

        <TextField
          label="Price"
          name="price"
          value={product.price}
          fullWidth
          onChange={handleChange}
          style={{ marginBottom: "20px", marginTop: "20px" }}
        />

        {/* ← Quantity Dropdown */}
        <FormControl fullWidth style={{ marginBottom: "20px", marginTop: "20px" }}>
          <InputLabel>Quantity</InputLabel>
          <Select
            label="Quantity"
            name="quantity"
            value={product.quantity}
            onChange={handleChange}
          >
            <MenuItem value="">Select Quantity</MenuItem>
            <MenuItem value="1">1</MenuItem>
            <MenuItem value="2">2</MenuItem>
            <MenuItem value="3">3</MenuItem>
            <MenuItem value="4">4</MenuItem>
            <MenuItem value="5">5</MenuItem>
            <MenuItem value="10">10</MenuItem>
            <MenuItem value="20">20</MenuItem>
            <MenuItem value="50">50</MenuItem>
            <MenuItem value="100">100</MenuItem>
          </Select>
        </FormControl>

        {/* ← Category Dropdown */}
        <FormControl fullWidth style={{ marginBottom: "20px", marginTop: "20px" }}>
          <InputLabel>Category</InputLabel>
          <Select
            label="Category"
            name="categoryId"
            value={product.categoryId}
            onChange={handleChange}
          >
            <MenuItem value="">Select Category</MenuItem>
            {categories.map((cat) => (
              <MenuItem key={cat._id} value={cat._id}>
                {cat.categoryName}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <Button variant='contained' fullWidth onClick={handleSubmit}>
          Submit
        </Button>

      </Paper>
    </div>
  );
}